"use client";
import React, { useState } from "react";
import { useForm } from "../hooks/useForm";
import { renderField } from "../core/renderField";
import "../core/field.css";

const StepForm = ({
  schema,
  onSubmit,
  apiError,
  loading,
  type,
  stepShow,
  errorType,
}) => {
  const [step, setStep] = useState(0);
  const [submittedData, setSubmittedData] = useState(null); // ✅ NEW
  const currentFields = schema.steps[step].fields;
  const { values, errors, handleChange, validateAll } = useForm(currentFields);
  const [showPopup, setShowPopup] = useState(false);

  // const next = () => {
  //   if (!validateAll()) return;
  //   setStep((prev) => prev + 1);
  // };

  const next = () => {
    const isValid = validateAll();

    if (!isValid) {
      setShowPopup(true); // 🔥 show popup
      return;
    }

    setStep((prev) => prev + 1);
  };

  const prev = () => setStep((prev) => prev - 1);

  // const handleSubmit = async () => {
  //   if (!validateAll()) return;

  //   const res = await onSubmit(values);

  //   // 👉 only set success if NO error
  //   if (!apiError && res !== false) {
  //     setSubmittedData(values);
  //   }
  // };

  const handleSubmit = async () => {
    const isValid = validateAll();

    if (!isValid) {
      setShowPopup(true); // 🔥 show popup
      return;
    }

    const res = await onSubmit(values);

    if (!apiError && res !== false) {
      setSubmittedData(values);
    }
  };

  // =========================
  // ⏳ LOADING
  // =========================
  if (loading) {
    return (
      <div className="stepper-wrapper">
        <div className="stepper-container loader-box">
          <div className="loader-spinner"></div>
          <p className="loader-text">Processing...</p>
        </div>
      </div>
    );
  }

  // =========================
  // ❌ API ERROR (FROM PROPS)
  // =========================
  if (apiError) {
    return (
      <div className="stepper-wrapper">
        <div className="stepper-container error-box">
          <h2 className="error-title">❌ Error</h2>
          <p className="error-message">{apiError}</p>
        </div>
      </div>
    );
  }

  // ✅ SUCCESS SCREEN

  if (submittedData && !apiError) {
    return (
      <div className="stepper-wrapper">
        <div className="stepper-container success-box">
          <h2 className="success-title">✅ Submitted Data</h2>

          <div className="summary-list">
            {Object.keys(submittedData).map((key) => {
              const value = submittedData[key];

              return (
                <div key={key} className="summary-item">
                  <span className="summary-label">{key}</span>

                  <span className="summary-value">
                    {(() => {
                      if (value instanceof File) return value.name;
                      if (Array.isArray(value)) return value.join(", ");
                      if (typeof value === "object" && value !== null)
                        return "-";
                      return value?.toString() || "-";
                    })()}
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    );
  }

  if (type === "layoutTwo") {
    const hasErrors = Object.entries(errors).some(
      ([field, msg]) => msg && currentFields[field],
    );
    return (
      <div className="fv-wrapper">
        <div className="fv-container">
          {errorType === "popup" && showPopup && hasErrors && (
            <div className="fv-popup-overlay">
              <div className="fv-popup">
                <div className="fv-popup-header">
                  <h3>⚠️ Please fix the following errors</h3>
                  <button
                    className="fv-popup-close"
                    onClick={() => setShowPopup(false)}
                  >
                    ✕
                  </button>
                </div>

                <ul className="fv-popup-list">
                  {Object.entries(errors)
                    .filter(([field, msg]) => msg && currentFields[field]) // ✅ only current step
                    .map(([field, message]) => (
                      <li key={field}>
                        <strong>{currentFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    ))}
                </ul>
              </div>
            </div>
          )}

          {/* --- Step Indicator --- */}
          {stepShow && (
            <div className="fv-header">
              {schema.steps.map((_, index) => (
                <React.Fragment key={index}>
                  <div className="fv-step-item">
                    <div
                      className={`fv-step-circle ${
                        index === step
                          ? "active"
                          : index < step
                            ? "completed"
                            : ""
                      }`}
                    >
                      {index < step ? "✓" : index + 1}
                    </div>
                    <span
                      className={`fv-step-label ${
                        index === step ? "active" : ""
                      }`}
                    >
                      Step {index + 1}
                    </span>
                  </div>

                  {index !== schema.steps.length - 1 && (
                    <div
                      className={`fv-step-line ${index < step ? "active" : ""}`}
                    />
                  )}
                </React.Fragment>
              ))}
            </div>
          )}

          {errorType === "beforField" &&
            Object.entries(errors).some(
              ([field, msg]) => msg && currentFields[field],
            ) && (
              <div className="fv-error-summary">
                <ul>
                  {Object.entries(errors)
                    .filter(([field, msg]) => msg && currentFields[field]) // ✅ only current step fields
                    .map(([field, message]) => (
                      <li key={field}>
                        <strong>{currentFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    ))}
                </ul>
              </div>
            )}

          {/* --- Form Body --- */}
          <div className="fv-body">
            <h2 className="fv-title">{schema.steps[step].title}</h2>

            <div className="fv-fields">
              {Object.keys(currentFields).map((name) =>
                renderField(
                  name,
                  currentFields[name],
                  values[name],
                  handleChange,
                  errors[name],
                  errorType,
                ),
              )}
            </div>
          </div>

          {/* --- Footer Buttons --- */}
          <div className="fv-footer">
            {step > 0 ? (
              <button className="fv-btn fv-btn-back" onClick={prev}>
                Previous
              </button>
            ) : (
              <div />
            )}

            {step < schema.steps.length - 1 ? (
              <button className="fv-btn fv-btn-next" onClick={next}>
                Continue
              </button>
            ) : (
              <button className="fv-btn fv-btn-submit" onClick={handleSubmit}>
                Complete Registration
              </button>
            )}
          </div>
        </div>
      </div>
    );
  } else if (type === "layoutThree") {
    const hasErrors = Object.entries(errors).some(
      ([field, msg]) => msg && currentFields[field],
    );
    return (
      <div className="step3-wrapper">
        <div className="step3-container">
          {errorType === "popup" && showPopup && hasErrors && (
            <div className="fv-popup-overlay">
              <div className="fv-popup">
                <div className="fv-popup-header">
                  <h3>⚠️ Please fix the following errors</h3>
                  <button
                    className="fv-popup-close"
                    onClick={() => setShowPopup(false)}
                  >
                    ✕
                  </button>
                </div>

                <ul className="fv-popup-list">
                  {Object.entries(errors)
                    .filter(([field, msg]) => msg && currentFields[field]) // ✅ only current step
                    .map(([field, message]) => (
                      <li key={field}>
                        <strong>{currentFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    ))}
                </ul>
              </div>
            </div>
          )}

          {/* --- Progress Bar --- */}

          {stepShow && (
            <div className="step3-progress">
              <div
                className="step3-progress-bar"
                style={{
                  width: `${((step + 1) / schema.steps.length) * 100}%`,
                }}
              />
            </div>
          )}

          {errorType === "beforField" &&
            Object.entries(errors).some(
              ([field, msg]) => msg && currentFields[field],
            ) && (
              <div className="fv-error-summary">
                <ul>
                  {Object.entries(errors)
                    .filter(([field, msg]) => msg && currentFields[field]) // ✅ only current step fields
                    .map(([field, message]) => (
                      <li key={field}>
                        <strong>{currentFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    ))}
                </ul>
              </div>
            )}

          {/* --- Step Header --- */}
          <div className="step3-header">
            <h2 className="step3-title">{schema.steps[step].title}</h2>
            {stepShow && (
              <p className="step3-subtitle">
                Step {step + 1} of {schema.steps.length}
              </p>
            )}
          </div>

          {/* --- Fields --- */}
          <div className="step3-fields">
            {Object.keys(currentFields).map((name) =>
              renderField(
                name,
                currentFields[name],
                values[name],
                handleChange,
                errors[name],
                errorType,
              ),
            )}
          </div>

          {/* --- Footer --- */}
          <div className="step3-footer">
            {step > 0 ? (
              <button className="step3-btn back" onClick={prev}>
                ← Back
              </button>
            ) : (
              <div />
            )}

            {step < schema.steps.length - 1 ? (
              <button className="step3-btn next" onClick={next}>
                Next →
              </button>
            ) : (
              <button className="step3-btn submit" onClick={handleSubmit}>
                Finish ✓
              </button>
            )}
          </div>
        </div>
      </div>
    );
  } else {
    const hasErrors = Object.entries(errors).some(
      ([field, msg]) => msg && currentFields[field],
    );
    return (
      <div className="stepper-wrapper">
        <div className="stepper-container">
          {errorType === "popup" && showPopup && hasErrors && (
            <div className="fv-popup-overlay">
              <div className="fv-popup">
                <div className="fv-popup-header">
                  <h3>⚠️ Please fix the following errors</h3>
                  <button
                    className="fv-popup-close"
                    onClick={() => setShowPopup(false)}
                  >
                    ✕
                  </button>
                </div>

                <ul className="fv-popup-list">
                  {Object.entries(errors)
                    .filter(([field, msg]) => msg && currentFields[field]) // ✅ only current step
                    .map(([field, message]) => (
                      <li key={field}>
                        <strong>{currentFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    ))}
                </ul>
              </div>
            </div>
          )}

          {/* --- Step Indicator --- */}
          {stepShow && (
            <div className="stepper-header">
              {schema.steps.map((_, index) => (
                <React.Fragment key={index}>
                  <div className="stepper-item">
                    <div
                      className={`stepper-circle ${index === step ? "active" : index < step ? "completed" : ""}`}
                    >
                      {index < step ? "✓" : index + 1}
                    </div>
                    <span
                      className={`stepper-label ${index === step ? "active" : ""}`}
                    >
                      Step {index + 1}
                    </span>
                  </div>
                  {index !== schema.steps.length - 1 && (
                    <div
                      className={`stepper-line ${index < step ? "active" : ""}`}
                    />
                  )}
                </React.Fragment>
              ))}
            </div>
          )}

          {errorType === "beforField" &&
            Object.entries(errors).some(
              ([field, msg]) => msg && currentFields[field],
            ) && (
              <div className="fv-error-summary">
                <ul>
                  {Object.entries(errors)
                    .filter(([field, msg]) => msg && currentFields[field]) // ✅ only current step fields
                    .map(([field, message]) => (
                      <li key={field}>
                        <strong>{currentFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    ))}
                </ul>
              </div>
            )}

          {/* --- Form Body --- */}
          <div className="stepper-body">
            <h2 className="stepper-title">{schema.steps[step].title}</h2>
            <div className="stepper-fields">
              {Object.keys(currentFields).map((name) =>
                renderField(
                  name,
                  currentFields[name],
                  values[name],
                  handleChange,
                  errors[name],
                  errorType,
                ),
              )}
            </div>
          </div>

          {/* --- Footer Buttons --- */}
          <div className="stepper-footer">
            {step > 0 ? (
              <button className="stepper-btn-back" onClick={prev}>
                Previous
              </button>
            ) : (
              <div />
            )}

            {step < schema.steps.length - 1 ? (
              <button className="stepper-btn-next" onClick={next}>
                Continue
              </button>
            ) : (
              <button className="stepper-btn-submit" onClick={handleSubmit}>
                Complete Registration
              </button>
            )}
          </div>
        </div>
      </div>
    );
  }
};

export default StepForm;
