"use client";

import React, { useState } from "react";
import { useForm } from "../hooks/useForm";
import { renderField } from "../core/renderField";
import "../core/field.css";

const Form = ({
  schema,
  onSubmit,
  apiError,
  loading,
  errorType,
  type,
  gridType = 2,
}) => {
  const { fields } = schema;
  const { values, errors, handleChange, validateAll } = useForm(fields);

  const [submittedData, setSubmittedData] = useState(null); // ✅ NEW
  const [showPopup, setShowPopup] = useState(true);

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateAll()) {
      setShowPopup(true); // ✅ open popup when validation fails
      return;
    }

    const res = await onSubmit(values);

    // ✅ success only if no API error
    if (!apiError && res !== false) {
      setSubmittedData(values);
    }
  };

  // =========================
  // ⏳ LOADING
  // =========================
  if (loading) {
    return (
      <div className="form-wrapper">
        <div className="form-container loader-box">
          <div className="loader-spinner"></div>
          <p className="loader-text">Processing...</p>
        </div>
      </div>
    );
  }

  // =========================
  // ❌ API ERROR
  // =========================
  if (apiError) {
    return (
      <div className="form-wrapper">
        <div className="form-container error-box">
          <h2 className="error-title">❌ Error</h2>
          <p className="error-message">{apiError}</p>
        </div>
      </div>
    );
  }

  // =========================
  // ✅ SUCCESS SCREEN
  // =========================
  if (submittedData && !apiError) {
    return (
      <div className="form-wrapper">
        <div className="form-container success-box">
          <h2 className="success-title">✅ Submitted Data</h2>

          <div className="summary-list">
            {Object.keys(submittedData).map((key) => {
              const value = submittedData[key];

              return (
                <div key={key} className="summary-item">
                  <span className="summary-label">{key}</span>

                  <span className="summary-value">
                    {(() => {
                      if (value instanceof File) return value.name;
                      if (Array.isArray(value)) return value.join(", ");
                      if (typeof value === "object" && value !== null)
                        return "-";
                      return value?.toString() || "-";
                    })()}
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    );
  }

  if (type === "layoutTwo") {
    const hasErrors = Object.values(errors).some((msg) => msg);
    return (
      <div className="fv2-wrapper">
        <div className="fv2-container">
          {errorType === "popup" && showPopup && hasErrors && (
            <div className="fv-popup-overlay">
              <div className="fv-popup">
                <div className="fv-popup-header">
                  <h3>⚠️ Please fix the following errors</h3>
                  <button
                    className="fv-popup-close"
                    onClick={() => setShowPopup(false)}
                  >
                    ✕
                  </button>
                </div>

                <ul className="fv-popup-list">
                  {Object.entries(errors).map(([field, message]) => {
                    if (!message) return null;

                    return (
                      <li key={field}>
                        <strong>{fields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    );
                  })}
                </ul>
              </div>
            </div>
          )}
          <form onSubmit={handleSubmit} className="fv2-form">
            {Object.keys(errors).length > 0 && errorType === "beforField" && (
              <div className="fv-error-summary">
                <ul>
                  {Object.entries(errors).map(([field, message]) => {
                    if (!message) return null; // ✅ skip empty messages

                    return (
                      <li key={field}>
                        <strong>{fields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    );
                  })}
                </ul>
              </div>
            )}
            <div
              className="fv2-grid"
              style={{
                gridTemplateColumns: `repeat(${gridType}, 1fr)`,
              }}
            >
              {Object.keys(fields).map((name) => (
                <div className="fv2-field" key={name}>
                  {renderField(
                    name,
                    fields[name],
                    values[name],
                    handleChange,
                    errors[name],
                    errorType,
                  )}
                </div>
              ))}
            </div>

            <div className="fv2-footer">
              <button type="submit" className="fv2-btn">
                Submit Details
              </button>
            </div>
          </form>
        </div>
      </div>
    );
  } else if (type === "layoutThree") {
    const hasErrors = Object.values(errors).some((msg) => msg);
    return (
      <div className="fv4-wrapper">
        <div className="fv4-container">
          {errorType === "popup" && showPopup && hasErrors && (
            <div className="fv-popup-overlay">
              <div className="fv-popup">
                <div className="fv-popup-header">
                  <h3>⚠️ Please fix the following errors</h3>
                  <button
                    className="fv-popup-close"
                    onClick={() => setShowPopup(false)}
                  >
                    ✕
                  </button>
                </div>

                <ul className="fv-popup-list">
                  {Object.entries(errors).map(([field, message]) => {
                    if (!message) return null;

                    return (
                      <li key={field}>
                        <strong>{fields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    );
                  })}
                </ul>
              </div>
            </div>
          )}
          {/* Form */}
          <form onSubmit={handleSubmit} className="fv4-form">
            {Object.keys(errors).length > 0 && errorType === "beforField" && (
              <div className="fv-error-summary">
                <ul>
                  {Object.entries(errors).map(([field, message]) => {
                    if (!message) return null; // ✅ skip empty messages

                    return (
                      <li key={field}>
                        <strong>{fields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    );
                  })}
                </ul>
              </div>
            )}
            <div className="fv4-fields">
              {Object.keys(fields).map((name) => (
                <div className="fv4-field-box" key={name}>
                  {renderField(
                    name,
                    fields[name],
                    values[name],
                    handleChange,
                    errors[name],
                    errorType,
                  )}
                </div>
              ))}
            </div>

            {/* Action */}
            <div className="fv4-footer">
              <button type="submit" className="fv4-submit">
                Submit Form
              </button>
            </div>
          </form>
        </div>
      </div>
    );
  } else {
    const hasErrors = Object.values(errors).some((msg) => msg);
    return (
      <div className="form-wrapper">
        <div className="form-container">
          {errorType === "popup" && showPopup && hasErrors && (
            <div className="fv-popup-overlay">
              <div className="fv-popup">
                <div className="fv-popup-header">
                  <h3>⚠️ Please fix the following errors</h3>
                  <button
                    className="fv-popup-close"
                    onClick={() => setShowPopup(false)}
                  >
                    ✕
                  </button>
                </div>

                <ul className="fv-popup-list">
                  {Object.entries(errors).map(([field, message]) => {
                    if (!message) return null;

                    return (
                      <li key={field}>
                        <strong>{fields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    );
                  })}
                </ul>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="form-content">
            {/* ✅ GLOBAL ERROR TOP */}
            {Object.keys(errors).length > 0 && errorType === "beforField" && (
              <div className="fv-error-summary">
                <ul>
                  {Object.entries(errors).map(([field, message]) => {
                    if (!message) return null; // ✅ skip empty messages

                    return (
                      <li key={field}>
                        <strong>{fields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    );
                  })}
                </ul>
              </div>
            )}

            <div className="fields-grid">
              {Object.keys(fields).map((name) =>
                renderField(
                  name,
                  fields[name],
                  values[name],
                  handleChange,
                  errors[name],
                  errorType,
                ),
              )}
            </div>

            <button type="submit" className="submit-btn">
              Submit Details
            </button>
          </form>
        </div>
      </div>
    );
  }
};

export default Form;
