import { useState } from "react";
import { validateField } from "../core/validate";

export const useForm = (fields) => {
  const [values, setValues] = useState({});
  const [errors, setErrors] = useState({});

  const handleChange = (name, value) => {
    setValues((prev) => ({ ...prev, [name]: value }));

    const error = validateField(value, fields[name]?.rules);
    setErrors((prev) => ({ ...prev, [name]: error }));
  };

  const validateAll = () => {
    let newErrors = {};

    Object.keys(fields).forEach((key) => {
      const error = validateField(values[key], fields[key]?.rules);
      if (error) newErrors[key] = error;
    });

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  return { values, errors, handleChange, validateAll };
};